<script setup>
import ProductionPlanDetail from './ProductionPlanDetail.vue';
import FinishedCodeBadge from './FinishedCodeBadge.vue';
import { locationLabel } from "../location-label.js";
import {computed,onMounted,ref} from 'vue';
import {brewApi} from '../api';
const props=defineProps({permissions:{type:Array,default:()=>[]},currentUser:{type:Object,default:()=>({})},roles:{type:Array,default:()=>[]},initialCategory:{type:String,default:''}});
const factories=ref([]),factory=ref(''),category=ref(props.initialCategory),keyword=ref(''),page=ref(1),items=ref([]),total=ref(0),units=ref([]),loading=ref(false),error=ref(''),selected=ref(null),detail=ref(null),detailLoading=ref(false),detailError=ref(''),detailTab=ref('lots');
const productionPlanId=ref(null);
const productionStatus=value=>({fermenting:'发酵中',raw_ready:'生产完成 · 原液在罐',awaiting_packaging:'酿造完成 · 待包装',in_tank:'已进罐 · 生产中'}[value]||'原液在罐');
const entryAllowed=ref(false),entryOpen=ref(false),entrySaving=ref(false),entryError=ref(''),entryOptions=ref({factories:[],locations:[],products:[]}),entry=ref({factory_id:'',product_id:'',location_id:'',quantity:'',package_count:'',packaging_id:'',lot_name:'',supplier_lot:'',expiration_date:''}),productPickerOpen=ref(false),productKeyword=ref(''),productCategory=ref('');
const entryFactoryLocations=computed(()=>entryOptions.value.locations.filter(l=>String(l.factory_id)===String(entry.value.factory_id)));
const entryProduct=computed(()=>entryOptions.value.products.find(p=>String(p.id)===String(entry.value.product_id))||null);
const entryPackaging=computed(()=>entryProduct.value?.packages?.find(p=>String(p.id)===String(entry.value.packaging_id))||null);
const isPackagedFinished=computed(()=>entryProduct.value?.item_type==='finished_product'&&entryPackaging.value);
const packageKind=level=>({box:'箱',keg:'桶',bottle:'瓶',can:'罐'}[level]||'件');
const convertedStockQty=computed(()=>isPackagedFinished.value?(Number(entry.value.package_count)||0)*Number(entryPackaging.value.qty||0):Number(entry.value.quantity)||0);
const entryCompatibleLocations=computed(()=>{
  const allowedTypes={raw_material:['raw_material'],packaging_material:['packaging'],semi_finished:['semi_finished'],finished_product:['finished']};
  const types=allowedTypes[entryProduct.value?.item_type]||[];
  return entryFactoryLocations.value.filter(location=>types.includes(location.type));
});
const isBreweryManager=computed(()=>props.roles.some(role=>role.code==='brewery_manager'));
const showEntryFactory=computed(()=>!isBreweryManager.value&&entryOptions.value.factories.length>1);
const entryProducts=computed(()=>entryOptions.value.products.filter(p=>(!productCategory.value||p.category===productCategory.value)&&(!productKeyword.value||`${p.name} ${p.brand||''} ${p.supplier?.name||''} ${p.specification||''}`.toLowerCase().includes(productKeyword.value.toLowerCase()))));
const categories=[['','全部库存'],['malt','麦芽'],['adjunct','可发酵物 / 辅料'],['hop','啤酒花'],['yeast','酵母'],['packaging','包装材料'],['semi_finished','原液库存'],['finished','成品酒'],['other','其他']];
const categoryName=c=>categories.find(x=>x[0]===c)?.[1]||'原料';
const locationTypeName=type=>({raw_material:'原料库位',material_issue:'领料库位',packaging:'包装库位',qc:'待检库位',semi_finished:'半成品库位',finished:'成品库位',loss:'损耗库位'}[type]||'库存库位');
const number=(v)=>Number(v||0).toLocaleString('zh-CN',{maximumFractionDigits:3});
const today=new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'});
const lotStatus=lot=>lot.frozen?'已冻结':lot.expiration_date&&lot.expiration_date<today?'已过期':quality[lot.quality_status]||lot.quality_status;
const quality={qualified:'合格',pending:'待检',quarantine:'待检',rejected:'不合格'};
const state={draft:'待执行',in_progress:'生产中',in_tank:'已进罐 · 生产中',completed:'已完成',cancelled:'已取消',released:'已放行',pending:'待包装'};
const date=v=>v?new Date(/[zZ]|[+-]\d\d:\d\d$/.test(v)?v:`${v}Z`).toLocaleString('zh-CN',{hour12:false,timeZone:'Asia/Shanghai'}):'—';
const sourceName=value=>({'brew.production.plan':'生产计划','brew.material.requisition':'领料单','sale.order':'销售订单'}[value]||value);
const isBeer=computed(()=>['finished','semi_finished'].includes(detail.value?.product.category));
let loadId=0,detailId=0;
async function load(reset=false){if(reset)page.value=1;const id=++loadId;loading.value=true;error.value='';try{const data=await brewApi.browseStock({factory_id:factory.value,category:category.value,keyword:keyword.value,page:page.value,page_size:30});if(id!==loadId)return;items.value=data.items;total.value=data.total;units.value=data.units;factories.value=data.factories;}catch(e){if(id===loadId)error.value=e.message;}finally{if(id===loadId)loading.value=false;}}
async function openEntry(){entryError.value='';try{entryOptions.value=await brewApi.getOpeningStockOptions(isBreweryManager.value?'':factory.value);entryAllowed.value=true;const preferred=props.currentUser?.default_factory_id||'';const f=isBreweryManager.value?(entryOptions.value.factories.some(x=>String(x.id)===String(preferred))?String(preferred):String(entryOptions.value.factories[0]?.id||'')):entryOptions.value.factories.some(x=>String(x.id)===String(factory.value))?String(factory.value):entryOptions.value.factories.length===1?String(entryOptions.value.factories[0].id):'';entry.value={factory_id:f,product_id:'',location_id:'',quantity:'',package_count:'',packaging_id:'',lot_name:'',supplier_lot:'',expiration_date:''};productKeyword.value='';productCategory.value='';entryOpen.value=true;}catch(e){entryAllowed.value=false;entryError.value=e.message||'无法加载库存录入选项。';error.value=entryError.value;}}
async function saveEntry(){if(entrySaving.value)return;entrySaving.value=true;entryError.value='';try{await brewApi.createOpeningStock({...entry.value,quantity:convertedStockQty.value,package_count:entry.value.package_count?Number(entry.value.package_count):undefined});entryOpen.value=false;factory.value=entry.value.factory_id;await load(true);}catch(e){entryError.value=e.message||'库存新建失败。';}finally{entrySaving.value=false;}}
function chooseEntryProduct(product){entry.value.product_id=String(product.id);entry.value.lot_name='';entry.value.supplier_lot='';entry.value.quantity='';entry.value.package_count='';entry.value.packaging_id='';const types={raw_material:['raw_material'],packaging_material:['packaging'],semi_finished:['semi_finished'],finished_product:['finished']};const matches=entryOptions.value.locations.filter(location=>String(location.factory_id)===String(entry.value.factory_id)&&types[product.item_type]?.includes(location.type));entry.value.location_id=String(matches.length===1?matches[0].id:'');productPickerOpen.value=false;}
async function open(row,historyPage=1,keepTab=false){if(row.source_type==='production'){productionPlanId.value=row.plan_id;return;}const id=++detailId;selected.value=row;detailLoading.value=true;detailError.value='';if(historyPage===1&&!keepTab){detail.value=null;detailTab.value='lots';}try{const data=await brewApi.stockProduct(row.product.id,{factory_id:row.factory.id,history_page:historyPage});if(id===detailId)detail.value=data;}catch(e){if(id===detailId)detailError.value=e.message;}finally{if(id===detailId)detailLoading.value=false;}}
function close(){detailId++;selected.value=null;detail.value=null;}
onMounted(()=>{load();brewApi.getOpeningStockOptions().then(data=>{entryOptions.value=data;entryAllowed.value=true;}).catch(()=>{entryAllowed.value=false;});});
</script>
<template>
<section class="stock-browser">
<header class="stock-toolbar"><div class="stock-heading"><h3>酒厂库存</h3><p>查看库存余额、批次与生产来源</p></div><form class="stock-filters" @submit.prevent="load(true)"><label class="stock-factory-select"><span>酒厂</span><select v-model="factory" aria-label="选择酒厂" @change="load(true)"><option value="">全部授权酒厂</option><option v-for="f in factories" :key="f.id" :value="f.id">{{ f.name }}</option></select></label><input v-model.trim="keyword" aria-label="搜索库存" placeholder="成品编号、名称或批次"><button class="btn btn-sm btn-primary" type="submit">搜索</button><button class="btn btn-sm btn-outline" type="button" :disabled="loading" @click="load()">刷新</button><button v-if="entryAllowed" class="btn btn-sm btn-primary" type="button" @click="openEntry">新建库存</button></form></header>
<div class="stock-browser-layout"><aside class="stock-categories"><strong>库存分类</strong><button v-for="[key,label] in categories" :key="key" :class="{active:category===key}" @click="category=key;load(true)">{{ label }}</button></aside><main class="stock-content"><div class="stock-summary"><div><strong>{{ categoryName(category) }}</strong><span class="stock-count">{{ total }} 项</span></div><div class="stock-unit-balances"><span v-for="u in units" :key="u.unit"><template v-if="category!=='semi_finished'">可用 <b>{{ number(u.available) }}</b> {{ u.unit }}</template><template v-if="u.in_production">{{ category==='semi_finished'?'原液合计':' · 原液' }} <b>{{ number(u.in_production) }}</b> {{ u.unit }}<small v-if="u.estimated">（含计划估算 {{ number(u.estimated) }} {{ u.unit }}）</small></template></span></div></div><div v-if="error" class="master-error">{{ error }}</div><div v-if="loading" class="empty">正在加载库存…</div><div v-else class="work-table-wrap"><table v-if="category==='semi_finished'" class="work-table"><thead><tr><th>酒款 / 成品编号</th><th>酒厂 / 罐号</th><th>原液库存量</th><th>数量依据</th><th>状态</th><th>已包装 / 包装损耗</th><th></th></tr></thead><tbody><tr v-for="row in items" :key="row.source_type==='production'?'production:'+row.batch_id:row.factory.id+':'+row.product.id"><td><strong>{{ row.product.name }}</strong><div class="stock-finished-codes"><FinishedCodeBadge :code="row.finished_product_code" /></div><small>生产批次 {{ row.batch_name || '未关联' }}</small></td><td>{{ row.factory.name }}<small>{{ row.tank_verified===false?'计划罐位：'+(row.tank||'未指定'):row.tank || '见库存库位' }}</small></td><td><strong>{{ number(row.on_hand) }} {{ row.product.unit }}</strong></td><td>{{ row.source_type==='production'?(row.volume_basis==='actual'?'实际记录量扣减包装':'计划量估算 · 待录实际量'):'账面库存' }}</td><td>{{ row.source_type==='production'?(row.tank_verified===false?'原液待核对':productionStatus(row.production_status)):'库存酒液' }}</td><td>{{ number(row.packaged_volume_l) }} L / {{ number(row.packaging_loss_l) }} L</td><td><button class="btn btn-xs btn-outline" @click="open(row)">{{ row.source_type==='production'?'生产详情':'库存详情' }}</button></td></tr></tbody></table><table v-else class="work-table"><thead><tr><th>物料 / 规格</th><th>酒厂</th><th>账面库存</th><th>已占用</th><th>可用库存</th><th title="待检、冻结、过期及已领用暂存的库存">不可用</th><th>批次 / 有效期</th><th></th></tr></thead><tbody><tr v-for="row in items" :key="row.source_type==='production'?'production:'+row.batch_id:row.factory.id+':'+row.product.id"><td><div class="stock-item-main"><span class="stock-item-image"><img v-if="row.product.image_url" :src="row.product.image_url" :alt="row.product.name"><template v-else>{{ (row.product.name||'物').slice(0,1) }}</template></span><div><strong>{{ row.product.name }}</strong><div v-if="row.finished_product_code || row.finished_product_codes?.length" class="stock-finished-codes"><FinishedCodeBadge v-for="code in row.finished_product_code ? [row.finished_product_code] : row.finished_product_codes" :key="code" :code="code" /></div><small v-else-if="['finished','semi_finished'].includes(row.product.category)" class="finished-code-missing">成品编号未关联</small><small v-if="row.source_type==='production'">{{ row.batch_name }} · {{ row.tank_verified===false?'原液待核对':row.tank+' · '+productionStatus(row.production_status) }}</small><small>{{ row.product.beer_type||categoryName(row.product.category) }}<template v-if="row.product.specification"> · {{ row.product.specification }}</template></small></div></div></td><td>{{ row.factory.name }}</td><td>{{ number(row.on_hand) }} {{ row.product.unit }}<small v-if="row.source_type==='production'">{{ row.volume_basis==='actual'?'实际记录量':'计划量估算' }}</small></td><td>{{ number(row.reserved) }} {{ row.product.unit }}</td><td class="stock-available">{{ number(row.available) }} {{ row.product.unit }}</td><td>{{ number(row.blocked) }} {{ row.product.unit }}</td><td>{{ row.lot_count }} 批<small>{{ row.earliest_expiration||'无有效期' }}</small></td><td><button class="btn btn-xs btn-outline" @click="open(row)">查看详情</button></td></tr></tbody></table><div v-if="!items.length" class="empty">该酒厂及分类暂无库存。</div></div><footer class="stock-pagination"><button class="btn btn-xs btn-outline" :disabled="page<=1||loading" @click="page--;load()">上一页</button><span>{{ page }} / {{ Math.max(1,Math.ceil(total/30)) }}</span><button class="btn btn-xs btn-outline" :disabled="page*30>=total||loading" @click="page++;load()">下一页</button></footer></main></div>
<Teleport to="body"><div v-if="selected" class="equipment-modal-mask" @click.self="close"><section class="equipment-modal stock-detail" role="dialog" aria-modal="true" aria-label="库存详情"><header class="equipment-modal-header"><div><div class="modal-title">{{ selected.product.name }}</div><div class="modal-subtitle">{{ selected.factory.name }} · {{ selected.product.beer_type||categoryName(selected.product.category) }}</div></div><button class="equipment-close" @click="close">×</button></header><div class="stock-detail-body"><div v-if="detailError" class="master-error">{{ detailError }}</div><div v-if="detailLoading&&!detail" class="empty">正在加载详情…</div><template v-if="detail"><div class="stock-detail-totals"><div v-for="[key,label] in [['on_hand','账面库存'],['reserved','已占用'],['available','可用库存'],['blocked','不可用 / 领料暂存']]" :key="key"><span>{{ label }}</span><strong>{{ number(detail[key]) }} <small>{{ detail.product.unit }}</small></strong></div></div><section class="stock-material-info"><h4>{{ isBeer ? '产品主要信息' : '材料主要信息' }}</h4><dl><div v-for="field in detail.product.important_details || []" :key="field.label"><dt>{{ field.label }}</dt><dd>{{ field.value }}</dd></div></dl></section><nav class="stock-detail-tabs"><button v-for="[key,label] in [['lots','库存批次'],['locations','库位分布'],['reservations','库存占用'],['movements','出入库记录'],...(isBeer?[['production','生产历史']]:[])]" :key="key" class="btn btn-sm" :class="detailTab===key?'btn-primary':'btn-outline'" @click="detailTab=key">{{ label }}</button></nav>
<div v-if="detailTab==='lots'" class="work-table-wrap"><table class="work-table"><thead><tr><th>库存批次 / 成品编号</th><th>供应商 / 生产批次</th><th>数量</th><th>可用</th><th>状态</th><th>有效期</th><th>库位</th></tr></thead><tbody><tr v-for="lot in detail.lots" :key="lot.id"><td><strong>{{ lot.name }}</strong><div v-if="lot.finished_product_code" class="stock-finished-codes"><FinishedCodeBadge :code="lot.finished_product_code" /></div><small>{{ lot.supplier_lot||(lot.manual_packaging?`${lot.manual_packaging.count}${packageKind(lot.manual_packaging.level)} · ${lot.manual_packaging.name}`:lot.packaging)||'—' }}</small></td><td>{{ lot.source_batch||lot.supplier||'—' }}</td><td>{{ number(lot.on_hand) }} {{ lot.uom }}</td><td class="stock-available">{{ number(lot.available) }} {{ lot.uom }}</td><td>{{ lotStatus(lot) }}<small v-if="lot.frozen">冻结：{{ lot.freeze_reason }}</small></td><td>{{ lot.expiration_date||'—' }}</td><td>{{ lot.locations.map(l=>locationLabel(l)).join('、') }}</td></tr></tbody></table><p v-if="!detail.lots.length" class="empty">没有批次信息，库存分布见库位页。</p></div>
<div v-if="detailTab==='locations'" class="work-table-wrap"><table class="work-table"><thead><tr><th>库位</th><th>账面</th><th>占用</th><th>可用</th></tr></thead><tbody><tr v-for="location in detail.locations" :key="location.id"><td>{{ locationLabel(location) }}</td><td>{{ number(location.on_hand) }} {{ detail.product.unit }}</td><td>{{ number(location.reserved) }} {{ detail.product.unit }}</td><td>{{ number(location.available) }} {{ detail.product.unit }}</td></tr></tbody></table></div>
<div v-if="detailTab==='reservations'" class="work-table-wrap"><table class="work-table"><thead><tr><th>占用来源</th><th>数量</th><th>到期时间</th></tr></thead><tbody><tr v-for="r in detail.reservations" :key="r.id"><td>{{ sourceName(r.source) }} #{{ r.source_id }}</td><td>{{ number(r.quantity) }} {{ detail.product.unit }}</td><td>{{ date(r.expires_at) }}</td></tr></tbody></table><p v-if="!detail.reservations.length" class="empty">暂无业务预占记录。</p></div>
<div v-if="detailTab==='movements'" class="work-table-wrap"><p class="stock-detail-note">最近 50 条出入库记录</p><table class="work-table"><thead><tr><th>时间</th><th>单据</th><th>批次</th><th>数量</th><th>来源 → 去向</th></tr></thead><tbody><tr v-for="m in detail.movements" :key="m.id"><td>{{ date(m.date) }}</td><td>{{ m.source?.reference||'—' }}</td><td>{{ m.lot?.name||'—' }}</td><td>{{ number(m.quantity) }} {{ m.uom }}</td><td>{{ locationLabel(m.source_location, '—') }} → {{ locationLabel(m.destination_location, '—') }}</td></tr></tbody></table><p v-if="!detail.movements.length" class="empty">暂无出入库记录。</p></div>
<div v-if="detailTab==='production'" class="stock-history"><article v-for="batch in detail.production_history" :key="batch.id"><header><strong>{{ batch.name }}</strong><span>{{ state[batch.state]||batch.state }} · {{ date(batch.created_at) }}</span></header><p>{{ batch.plan }} · {{ batch.recipe }} · {{ batch.tank }} · 计划 {{ number(batch.planned_volume_l) }} L / 实际 {{ number(batch.actual_volume_l) }} L</p><div v-for="pack in batch.packaging" :key="pack.name">{{ pack.name }} · {{ pack.specification }} · 成品批次 {{ pack.lot||'未生成' }} · {{ number(pack.quantity) }} 件 / {{ number(pack.volume_l) }} L · {{ state[pack.state]||pack.state }}</div></article><p v-if="!detail.production_history.length" class="empty">暂无关联生产批次。</p><footer class="stock-pagination"><span>共 {{ detail.history_total }} 个生产批次</span><button class="btn btn-xs btn-outline" :disabled="detail.history_page<=1||detailLoading" @click="open(selected,detail.history_page-1,true)">上一页</button><button class="btn btn-xs btn-outline" :disabled="detail.history_page*20>=detail.history_total||detailLoading" @click="open(selected,detail.history_page+1,true)">下一页</button></footer></div>
</template></div><footer class="equipment-modal-footer"><button class="btn btn-secondary" @click="close">关闭</button></footer></section></div></Teleport>
<Teleport to="body"><div v-if="entryOpen" class="equipment-modal-mask" @click.self="entryOpen=false"><form class="equipment-modal stock-entry-modal" role="dialog" aria-modal="true" aria-label="新建库存" @submit.prevent="saveEntry"><header class="equipment-modal-header"><div><div class="modal-title">新建库存</div><div class="modal-subtitle">按包装规格录入成品数量，并记录库位和批次</div></div><button type="button" class="equipment-close" @click="entryOpen=false">×</button></header><div class="stock-entry-body"><div v-if="entryError" class="master-error">{{ entryError }}</div><label v-if="showEntryFactory"><span>酒厂</span><select v-model="entry.factory_id" required @change="entry.location_id=''"><option value="" disabled>选择酒厂</option><option v-for="f in entryOptions.factories" :key="f.id" :value="String(f.id)">{{ f.name }}</option></select></label><div class="stock-entry-product"><span>商品</span><button type="button" class="stock-product-picker-trigger" @click="productPickerOpen=true">{{ entryProduct ? entryProduct.name : '点击选择供应商商品' }}<b>选择商品　⌄</b></button><div v-if="entryProduct" class="stock-selected-product"><strong>{{ entryProduct.supplier?.name||'酒厂物料' }}</strong><span>{{ entryProduct.brand||'' }}<template v-if="entryProduct.specification"> · {{ entryProduct.specification }}</template></span><span>库存单位：{{ entryProduct.unit }}<template v-if="entryProduct.price!=null"> · 参考价：¥{{ entryProduct.price }} / {{ entryProduct.unit }}</template></span></div><small v-else class="stock-entry-field-hint">从当前可用原料、包装材料和产品中选择</small></div><label v-if="entryProduct?.item_type==='finished_product'&&entryProduct.packages?.length" class="stock-entry-packaging"><span>包装规格</span><select v-model="entry.packaging_id" required @change="entry.package_count=''"><option value="" disabled>选择系统已配置的包装类型</option><option v-for="p in entryProduct.packages" :key="p.id" :value="String(p.id)">{{ p.name }} · {{ packageKind(p.level) }}装 · {{ number(p.qty) }} {{ entryProduct.unit }} / {{ packageKind(p.level) }}<template v-if="p.volu